import React, { useEffect, useRef, useState } from 'react';
import { Col, Row, Form, Button, Card, Accordion } from 'react-bootstrap';
import { useForm, Controller } from 'react-hook-form';
import ReactQuill from 'react-quill';
import { createSuggestionAction } from '../../../../../redux/suggestions/action';
import SuggestionOffcanvas from '../SuggestionOffcanvas';
import { useDispatch, useSelector } from 'react-redux';
import {
    createAlcoholHistoryAction,
    deleteAlcoholHistoryAction,
    getAlcoholHistoryAction,
    updateAlcoholHistoryAction,
} from '../../../../../redux/socialHistory/action';
import { encryptMessage } from '../../../../../cryptoUtils';
import { useSearchParams } from 'react-router-dom';
import DeletionModal from '../../../../../helpers/deletionModal';
import Spinner from '../../../../../constants/Spinner';
import ToastHandle from '../../../../../helpers/ToastMessage';
import useQuillWordLimit from '../../../../../helpers/quillWordLimit';

const MAX_WORDS = 1000;
const MAX_WORD_LENGTH = 45;

const Alcohol = () => {
    const dispatch = useDispatch();
    const quillRef = useRef(null);
    const [searchParams] = useSearchParams();
    const patientId = searchParams.get('id');
    const store = useSelector((state) => state);

    // State declarations
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [toDelete, setToDelete] = useState(null);
    const [toEdit, setToEdit] = useState(null);
    const [deleteModal, setDeleteModal] = useState(false);

    // Selectors
    const createResponse = store?.createAlcoholHistoryReducer?.data?.status;
    const loading = store?.getAlcoholHistoryReducer?.loading;
    const deleteResponse = store?.deleteAlcoholHistoryReducer?.data?.status;
    const updateResponse = store?.updateAlcoholHistoryReducer?.data?.status;
    const alcoholData = store?.getAlcoholHistoryReducer?.data?.data;

    // Form handling
    const { register, handleSubmit, reset, formState: { errors }, control, watch, getValues, setValue } = useForm();
    const watchUseStatus = watch('useStatus');
    const heavyFrequency = watch('frequency');

    useEffect(() => {
        if (!alcoholData) {
            dispatch(getAlcoholHistoryAction({ patientId }));
        }
    }, [alcoholData, dispatch]);

    useEffect(() => {
        if (toEdit) {
            setValue('useStatus', toEdit?.useStatus || '');
            setValue('alcoholType', toEdit?.alcoholType || '');
            setValue('frequency', toEdit?.frequency || '');
            setValue('quantityPerOccasion', toEdit?.quantityPerOccasion || '');
            setValue('hasDependenceSymptoms', toEdit?.hasDependenceSymptoms || '');
            setValue('heavyIntakeFrequency', toEdit?.heavyIntakeFrequency || '');
            setValue('note', toEdit?.note?.[0]?.text || '<ul><li></li></ul>');
            setValue('ageOfFirstUse', toEdit?.ageOfFirstUse || '');
            setValue(
                'lastUseDate',
                toEdit?.lastUseDate ? new Date(toEdit?.lastUseDate)?.toISOString().split('T')[0] : ''
            );
            setValue('reasonForStopping', toEdit?.reasonForStopping || '');
        }
    }, [toEdit]);

    const closeDeleteModal = () => {
        setDeleteModal(false);
        setToDelete(null);
        setToEdit(null);
    };

    const deleteHistory = () => {
        dispatch(deleteAlcoholHistoryAction({ id: toDelete }));
    };

    useEffect(() => {
        if (createResponse === 201 || updateResponse === 200) {
            reset();
            setToEdit(null);
            dispatch(getAlcoholHistoryAction({ patientId: patientId }));
        }
    }, [createResponse, updateResponse]);

    useEffect(() => {
        if (deleteResponse === 200) {
            reset();
            closeDeleteModal();
            dispatch(getAlcoholHistoryAction({ patientId: patientId }));
        }
    }, [deleteResponse]);

    useEffect(() => {
        if (watchUseStatus === 'Current User') {
            setValue('ageOfFirstUse', '');
            setValue('lastUseDate', '');
            setValue('reasonForStopping', '');
        } else if (watchUseStatus === 'Former User') {
            setValue('frequency', '');
            setValue('quantityPerOccasion', '');
            setValue('heavyIntakeFrequency', '');
            setValue('alcoholType', '');
            setValue('hasDependenceSymptoms', '');
        } else {
            setValue('frequency', '');
            setValue('quantityPerOccasion', '');
            setValue('heavyIntakeFrequency', '');
            setValue('alcoholType', '');
            setValue('hasDependenceSymptoms', '');
            setValue('ageOfFirstUse', '');
            setValue('lastUseDate', '');
            setValue('reasonForStopping', '');
        }
    }, [watchUseStatus, setValue]);

    const onSubmit = (data) => {
        Object.keys(data).forEach((key) => {
            if (data[key] === '') {
                delete data[key];
            }
        });

        // Remove note from data to prevent it from being included via spread
        const { note, ...dataWithoutNote } = data;

        const payload = {
            ...dataWithoutNote,
            subject: patientId,
            effectiveDateTime: new Date().toISOString(),
            ...(note && note.trim() !== '' && note !== '<ul><li></li></ul>' && note !== '<p><br></p>' && {
                note: [
                    {
                        text: note,
                        time: new Date().toISOString(),
                    },
                ],
            }),
        };
        if (toEdit) {
            payload.id = toEdit?._id;
            dispatch(updateAlcoholHistoryAction({ key: encryptMessage(payload) }));
        } else {
            dispatch(createAlcoholHistoryAction({ key: encryptMessage(payload) }));
        }
    };

    const handleEditorFocus = () => {
        dispatch(createSuggestionAction({ module: 'alcohol' }));
        setShowSuggestions(true);
    };

    const handleSuggestionSelect = (suggestionText) => {
        const current = getValues('note');
        setValue('note', `${current}<p>${suggestionText}</p>`);
    };

    const handleReset = () => {
        reset();
        setToEdit(null);
        setToDelete(null);
        setDeleteModal(false);
        setValue('note', '<ul><li></li></ul>');
        setShowSuggestions(false);
    };

    const handleLimitExceed = ({ type, message }) => {
        ToastHandle(message, 'danger');
    };

    useQuillWordLimit({
        quillRef,
        maxWords: MAX_WORDS,
        maxWordLength: MAX_WORD_LENGTH,
        onLimitExceed: handleLimitExceed,
        setValue,
        fieldName: 'note',
    });

    return (
        <Row className="g-0 m-0" style={{ height: 'calc(100vh - 150px)' }}>
            {/* Left: Form Section */}
            <Col md={6} className="d-flex flex-column border-end px-0 pe-2" style={{ height: '100%' }}>
                <div className="h-100">
                    <div className="d-flex flex-column px-2 py-0">
                        <Form
                            onSubmit={handleSubmit(onSubmit)}
                            className="flex-grow-1 d-flex flex-column"
                            style={{ height: '100%' }}
                        >
                            <div className='scroll-container px-0' style={{ height: '40vh', overflowX: "hidden" }}>
                                <Row className="">
                                    <Col sm={12}>
                                        <Form.Group>
                                            <Form.Label className="fw-medium mb-1">Alcohol Use Status</Form.Label>
                                            <Form.Select {...register('useStatus', { required: true })} required>
                                                <option value="">Select status</option>
                                                <option value="Current User">Current User</option>
                                                <option value="Former User">Former User</option>
                                                <option value="Never Used">Never Used</option>
                                                <option value="Unknown">Unknown</option>
                                            </Form.Select>
                                        </Form.Group>
                                    </Col>

                                    {watchUseStatus === 'Current User' && (
                                        <>
                                            <Col sm={6}>
                                                <Form.Group>
                                                    <Form.Label className="fw-medium mb-1">
                                                        Alcohol use frequency <span className="text-danger">*</span>
                                                    </Form.Label>
                                                    <Form.Select {...register('frequency', {
                                                        required: 'Alcohol use frequency is required'
                                                    })}>
                                                        <option key="" value="">
                                                            Select
                                                        </option>
                                                        {['Occasionally', 'Weekly', 'Daily', 'Heavy', 'Unknown']?.sort((a, b) => a.localeCompare(b))?.map(
                                                            (data) => (
                                                                <option value={data} key={data}>
                                                                    {data}
                                                                </option>
                                                            )
                                                        )}
                                                    </Form.Select>
                                                    {errors.frequency && (
                                                        <div className="text-danger small">{errors.frequency.message}</div>
                                                    )}
                                                </Form.Group>
                                            </Col>

                                            <Col sm={6}>
                                                <Form.Group>
                                                    <Form.Label className="fw-medium mb-1">
                                                        Standard drinks per occasion <span className="text-danger">*</span>
                                                    </Form.Label>
                                                    <Form.Select {...register('quantityPerOccasion', {
                                                        required: 'Standard drinks per occasion is required'
                                                    })}>
                                                        <option key="" value="">
                                                            Select
                                                        </option>
                                                        {['1 or 2', '3 or 4', '5 or 6', '7 to 9', '10 or more']?.map(
                                                            (data) => (
                                                                <option value={data} key={data}>
                                                                    {data}
                                                                </option>
                                                            )
                                                        )}
                                                    </Form.Select>
                                                    {errors.quantityPerOccasion && (
                                                        <div className="text-danger small">{errors.quantityPerOccasion.message}</div>
                                                    )}
                                                </Form.Group>
                                            </Col>

                                            {heavyFrequency === 'Heavy' && (
                                                <Col sm={6}>
                                                    <Form.Group>
                                                        <Form.Label className="fw-medium mb-1">
                                                            Heavy intake frequency
                                                        </Form.Label>
                                                        <Form.Select {...register('heavyIntakeFrequency')} required>
                                                            <option key="" value="">
                                                                Select
                                                            </option>
                                                            {[
                                                                'Less than monthly',
                                                                'Monthly',
                                                                'Weekly',
                                                                'Daily or almost daily',
                                                            ]?.sort((a, b) => a.localeCompare(b))?.map((data) => (
                                                                <option value={data} key={data}>
                                                                    {data}
                                                                </option>
                                                            ))}
                                                        </Form.Select>
                                                    </Form.Group>
                                                </Col>
                                            )}

                                            <Col sm={6}>
                                                <Form.Group>
                                                    <Form.Label className="fw-medium mb-1">
                                                        What types of alcohol do you usually consume? <span className='text-danger'>*</span>
                                                    </Form.Label>
                                                    <Form.Select {...register('alcoholType',
                                                        { required: 'Alcohol type is required' }
                                                    )} >
                                                        <option key="" value="">
                                                            Select
                                                        </option>
                                                        {['Beer', 'Wine', 'Spirits', 'Other', 'All']?.sort((a, b) => a.localeCompare(b))?.map((data) => (
                                                            <option value={data} key={data}>
                                                                {data}
                                                            </option>
                                                        ))}
                                                    </Form.Select>
                                                    {errors.alcoholType && (
                                                        <span className="text-danger small">{errors.alcoholType.message}</span>
                                                    )}
                                                </Form.Group>
                                            </Col>

                                            <Col sm={6}>
                                                <Form.Group>
                                                    <Form.Label className="fw-medium mb-1">
                                                        Do you experience dependence symptoms (e.g., craving,
                                                        withdrawal)?
                                                    </Form.Label>
                                                    <Form.Check
                                                        type="checkbox"
                                                        label="Yes"
                                                        {...register('hasDependenceSymptoms')}
                                                    />
                                                </Form.Group>
                                            </Col>
                                        </>
                                    )}

                                    {watchUseStatus === 'Former User' && (
                                        <>
                                            <Col sm={6}>
                                                <Form.Group>
                                                    <Form.Label className="fw-medium mb-1">
                                                        Age when you started using alcohol
                                                    </Form.Label>
                                                    <Form.Control
                                                        type="number"
                                                        {...register('ageOfFirstUse', { valueAsNumber: true })}
                                                    />
                                                </Form.Group>
                                            </Col>

                                            <Col sm={6}>
                                                <Form.Group>
                                                    <Form.Label className="fw-medium mb-1">
                                                        Date of last alcohol use
                                                    </Form.Label>
                                                    <Form.Control
                                                        type="date"
                                                        max={new Date().toISOString().slice(0, 10)}
                                                        {...register('lastUseDate')}
                                                    />
                                                </Form.Group>
                                            </Col>

                                            <Col sm={12}>
                                                <Form.Group>
                                                    <Form.Label className="fw-medium mb-1">
                                                        Reason for stopping alcohol use
                                                    </Form.Label>
                                                    <Form.Control
                                                        as="textarea"
                                                        rows={2}
                                                        {...register('reasonForStopping')}
                                                    />
                                                </Form.Group>
                                            </Col>
                                        </>
                                    )}

                                    {watchUseStatus !== 'Never Used' && (
                                        <Col xs={12} className="flex-grow-1 d-flex flex-column">
                                            <Form.Group controlId="notes" className="flex-grow-1 d-flex flex-column">
                                                <Form.Label className="fw-medium mb-1 d-flex justify-content-between align-items-center">
                                                    <div>
                                                        Notes{' '}
                                                        <span
                                                            style={{ cursor: 'pointer' }}
                                                            title="Notes Suggestions"
                                                            onClick={handleEditorFocus}>
                                                            ✨
                                                        </span>
                                                    </div>
                                                    <small className="text-muted">
                                                        {(() => {
                                                            const content = watch('note') || '';
                                                            const plainText = quillRef?.current
                                                                ?.getEditor()
                                                                ?.getText()
                                                                ?.trim();
                                                            const words = plainText?.split(/\s+/)?.filter(Boolean);
                                                            const wordCount = words?.length;
                                                            return (
                                                                <div>
                                                                    <div>{`${wordCount} / ${MAX_WORDS} words`}</div>
                                                                </div>
                                                            );
                                                        })()}
                                                    </small>
                                                </Form.Label>

                                                <div className="flex-grow-1 d-flex flex-column">
                                                    <Controller
                                                        name="note"
                                                        control={control}
                                                        defaultValue="<ul><li></li></ul>"
                                                        render={({ field: { onChange, value } }) => (
                                                            <ReactQuill
                                                                value={value}
                                                                ref={quillRef}
                                                                onChange={(content, delta, source) => {
                                                                    if (source === 'user') {
                                                                        onChange(content);
                                                                    }
                                                                }}
                                                                theme="snow"
                                                                placeholder="Enter detailed notes here..."
                                                                style={{ height: '24vh', backgroundColor: 'white' }}
                                                                modules={{
                                                                    toolbar: [
                                                                        [{ header: [1, 2, false] }],
                                                                        ['bold', 'italic', 'underline', 'strike'],
                                                                        [{ list: 'ordered' }, { list: 'bullet' }],
                                                                        ['clean'],
                                                                    ],
                                                                }}
                                                            />
                                                        )}
                                                    />
                                                </div>
                                                <SuggestionOffcanvas
                                                    show={showSuggestions}
                                                    onClose={() => setShowSuggestions(false)}
                                                    onSelect={handleSuggestionSelect}
                                                />
                                            </Form.Group>
                                        </Col>
                                    )}
                                </Row>
                            </div>

                            <div className="mt-5 d-flex justify-content-end" style={{ height: '' }}>
                                <Button
                                    variant="primary"
                                    type="submit"
                                    className="px-3 py-1 custom-buttons"
                                    disabled={loading}>
                                    {toEdit ? 'Update' : 'Add Record'}
                                </Button>
                            </div>
                        </Form>
                    </div>
                </div>
            </Col>

            {/* Right: History Section */}
            <Col md={6} className="d-flex flex-column px-0" style={{ height: '100%' }}>
                <div className="h-100">
                    <div className="p-0" style={{ overflowY: 'auto' }}>
                        {store?.getAlcoholHistoryReducer?.loading && !alcoholData?.length ? (
                            <div className="text-center py-4">
                                <Spinner />
                            </div>
                        ) : alcoholData?.length === 0 ? (
                            <div className="text-center py-4 text-muted">
                                <i className="bi bi-journal-x fs-1"></i>
                                <p className="mt-2 mb-0">No alcohol use records found</p>
                            </div>
                        ) : (
                            <Accordion alwaysOpen flush className="h-100">
                                {alcoholData?.map((item, index) => (
                                    <Accordion.Item eventKey={index.toString()} key={index} className="rounded-1">
                                        <Accordion.Header>
                                            <div
                                                className="d-flex justify-content-between align-items-center w-100"
                                                style={{ marginRight: '-19px' }}>
                                                <div className="d-flex align-items-center gap-2 p-2 pe-0">
                                                    <span className="text-black fs-6 tab-font-family fw-semibold">
                                                        {index + 1}.
                                                    </span>
                                                    <span className="fw-normal fs-6 tab-font-family text-black">
                                                        {item?.useStatus?.length > 35
                                                            ? item?.useStatus?.slice(0, 34) + '...'
                                                            : item?.useStatus || ''}{' '}
                                                        <span className="fs-6 text-muted fw-semibold">
                                                            {item?.alcoholType && `(${item?.alcoholType})`}
                                                        </span>
                                                    </span>
                                                    <small className="text-black" style={{ fontSize: '12px' }}>
                                                        {item?.effectiveDateTime
                                                            ? `${new Date(item?.effectiveDateTime).toLocaleDateString()} (${new Date(item?.effectiveDateTime).toLocaleTimeString()})`
                                                            : 'No date'}
                                                    </small>
                                                </div>
                                                {/* Action Icons */}
                                                <div className="d-flex gap-2 px-2" onClick={(e) => e.stopPropagation()}>
                                                    <i
                                                        className="bi bi-trash text-danger cursor-pointer"
                                                        onClick={(e) => {
                                                            e.stopPropagation();
                                                            setToDelete(item?._id);
                                                            setDeleteModal(true);
                                                        }}
                                                        title="Delete"
                                                    />
                                                    {toEdit && toEdit._id === item._id ? (
                                                        <i
                                                            className="bi bi-x-lg text-danger cursor-pointer"
                                                            onClick={(e) => {
                                                                e.stopPropagation();
                                                                handleReset();
                                                            }}
                                                            title="Cancel"
                                                        />
                                                    ) : (
                                                        <i
                                                            className="bi bi-pencil text-info cursor-pointer"
                                                            onClick={(e) => {
                                                                e.stopPropagation();
                                                                setToEdit(item);
                                                            }}
                                                            title="Edit"
                                                        />
                                                    )}
                                                </div>
                                            </div>
                                        </Accordion.Header>

                                        <Accordion.Body className="pt-0 p-0">
                                            {item?.note?.[0]?.text ? (
                                                <div
                                                    className="ql-editor p-1 rounded"
                                                    dangerouslySetInnerHTML={{ __html: item.note[0].text }}
                                                    style={{
                                                        fontSize: '0.875rem',
                                                        maxHeight: '150px',
                                                        overflowY: 'auto',
                                                    }}
                                                />
                                            ) : (
                                                <div className="text-muted fst-italic p-2">No notes available</div>
                                            )}
                                        </Accordion.Body>
                                    </Accordion.Item>
                                ))}

                                <DeletionModal
                                    show={deleteModal}
                                    onHide={closeDeleteModal}
                                    onConfirm={deleteHistory}
                                    item="alcohol history"
                                    isLoading={store?.deleteAlcoholHistoryReducer?.loading}
                                />
                            </Accordion>
                        )}
                    </div>
                </div>
            </Col>
        </Row>
    );
};

export default Alcohol;
